"""Human-reviewed method/effect/assumption annotations, with primary sources."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
data={}


def add(pid,group,alias,idea,effect,why,limits,modules):
    data[pid]={'group':group,'alias':alias,'method':idea,'reported_effect':effect,
        'mechanism_interpretation':why,'conditions_and_limits':limits,'modules':modules.split('/')}


add('P01','机制基础','CoT prompting','给出含中间推导的少量示例，让模型生成推导再回答。','540B模型仅8个CoT示例即在GSM8K达到当时最强水平；还测算术、常识和符号任务。','把一次直接映射变成多次可条件化计算，推导成为外部工作区。','基础CoT并非今天万token长链；效果依赖模型规模、示例和任务，不能直接解释现代RL长链。','过程表征/解码策略')
add('P02','机制基础','Self-Consistency','采样多条不同推理路径，边缘化路径后按答案聚合。','作者摘要报告GSM8K +17.9、SVAMP +11.0、AQuA +12.2个百分点等增益。','用多路径降低单次贪心路径的偶然错误，关键是有效多样性。','并行采样不是单链变长；答案众数可一致地错，增加路径有实际成本。','搜索与分支/答案聚合')
add('P03','机制基础','Tree of Thoughts','以thought为节点，用评估和搜索实现前瞻、回退与多路线选择。','GPT-4在Game of 24由CoT的4%提高至74%。','把不可撤销的逐token承诺变成可比较、可回退的状态搜索。','提升来自特定规划任务和多次模型调用；74%不能外推到一般数学或同算力单链。','过程表征/搜索与分支/验证反馈')
add('P04','机制基础','Compute-optimal test-time scaling','按题目难度分配搜索验证与自我修订计算。','相对best-of-N，作者报告计算效率超过4倍；在特定FLOPs匹配条件下可超过14倍大的模型。','不同难度需要不同搜索深度/宽度，均匀撒算力浪费预算。','是FLOPs与成功率条件下的结果，不等于固定GPU墙钟快4倍；弱模型须有非零解题机会。','计算分配/搜索与分支/验证反馈')
add('P05','训练与自演化','s1','筛出1000条难度、覆盖和质量兼顾的轨迹SFT，再用budget forcing改变思考长度。','s1-32B在AIME24经budget forcing由50%到57%；训练使用16张H100约26分钟。','少量高质量轨迹激活行为模板，追加Wait使已有策略继续探索。','时间短不代表训练算力低；不同选样消融差异大，Wait不是通用正确性操作。','训练数据/行为策略/计算分配')
add('P06','验证与信用分配','PRM / Let’s Verify Step by Step','用每步人工反馈训练过程奖励模型，比较过程监督与终局监督。','代表性MATH测试子集解出78%；发布80万步级标签PRM800K。','把终局稀疏对错分解为可定位的中间质量反馈。','78%不是不带搜索的裸模型pass@1；依赖标注、采样和验证器，推理成本需另计。','验证反馈/训练监督/搜索与分支')
add('P07','验证与信用分配','SCoRe','在模型自己生成的两轮轨迹上做分阶段在线RL，先解耦两次作答，再奖励纠错进展。','Gemini系列上作者报告MATH自纠错改善15.6、HumanEval改善9.1个百分点。','同时处理离线纠错数据的分布偏移和不愿修改答案的行为塌缩；普通多轮RL也会塌缩。','需要专门训练及可验证奖励；两轮计算和单轮结果不应混比。','行为策略/纠错恢复/信用分配/训练分布')
add('P08','训练与自演化','Satori / COAT','用继续、反思和探索等meta-action组织思维链；格式热身后结合Restart-and-Explore与RL。','消融中RAE使MATH500由81.6到85.6、AMC2023由57.5到67.5；AIME24两者均20.0。','让训练见到正确和错误中间状态，奖励从错到对、惩罚从对到错，训练真实修订行为。','并非所有任务每个模块都提升；反思标记不证明有效反思，需按动作和收益验证。','过程表征/行为策略/纠错恢复/信用分配')
add('P09','训练与自演化','rStar-Math','用代码增强MCTS轨迹、过程偏好模型及多轮自演化训练小模型。','Qwen2.5-Math-7B在MATH由58.8%到90.0%；AIME平均53.3%。','搜索把稀有成功轨迹变成训练数据，策略与评估模型互相提高。','使用74.7万题、百万级轨迹和4轮演化；小参数模型不等于低总成本。','训练数据/搜索与分支/验证反馈/信用分配')
add('P10','表示与执行','L1 / LCPO','把目标长度作为条件，RL同时优化答对与长度遵循，并区分Exact和Max约束。','1.5B L1在相同短链长度下超过GPT-4o；长度可在512/1024/2048/3600等点控制。','把长度控制内化为策略，不只是临时切断输出。','Exact可能鼓励凑长度；Max约束更接近有限预算。训练4k上下文、评估8k，不能默认覆盖任意长链。','行为策略/训练目标/计算分配')
add('P11','表示与执行','ThinkPrune','逐轮缩紧token上限做RL，超长且未完成的输出得零奖励。','R1-Distill-Qwen-1.5B在AIME24推理长度减半，作者报告性能下降约2%。','让模型学习跳过低效过程，而非让未适应短链的模型被迫中断。','结论针对特定模型/任务；需要多轮训练和完整性评价。','训练目标/过程压缩')
add('P12','表示与执行','Chain of Draft','用极简但保留关键信息的草稿式中间表达替代冗长说明。','在部分任务中以低至CoT 7.6%的token达到相当或更高准确率。','压缩外显语言冗余，保留有用推导；不必减少所有语义计算。','7.6%是特定设置，不能当所有任务平均；极复杂推导可能损失必要细节。','过程表征/过程压缩')
add('P13','表示与执行','TALE','估计题目所需token预算，把预算要求加入推理提示。','正式摘要报告明显降低token成本、仅轻微性能下降；本轮不填未核对的统一降幅。','先约束表达和计算投入，利用模型对长度指令的适应能力。','预算估错会欠推理；token减少不等于同等比例的真实延迟下降。','计算分配/行为策略')
add('P14','表示与执行','Coconut','把末层hidden state直接反馈为下一输入，用多阶段课程将显式步骤替换为连续thought。','ProsQA：97.0%对CoT 77.5%；GSM8K：34.1%低于CoT 42.9%；去掉课程后ProsQA降至76.1%。','延缓离散单路径承诺，允许连续状态表示多个候选；课程是对齐接口的重要条件。','不是潜空间在所有任务都优越；其BFS解释有探针支持但不等于每一步精确枚举。','过程表征/潜空间/训练监督')
add('P15','表示与执行','Soft Thinking','以词分布加权embedding形成连续概念token，并用Cold Stop处理低熵和潜式塌缩。','数学/代码基准上最高提升pass@1 2.48个百分点，同时最高减少22.4% token。','保持下一步分布信息，减少过早离散选择；停止模块同时缓解OOD连续输入。','两个最高值不必来自同一设置；相同文本词元数、latent步数和墙钟不是一个指标。','潜空间/解码策略/终止控制')
add('P16','机制基础','Pause Tokens','预训练和微调时加入可学习pause token，让输出前有额外计算。','1B模型9项任务中8项提高；摘要报告SQuAD约18%、CommonsenseQA约8%、GSM8K约1%的指标增益。','附加计算可以不承载自然语言推导，但模型必须学会利用它。','不是给任意现成模型插空白就有效；原实验要求预训练和微调均带pause。','潜空间/训练监督/计算深度')
add('P17','机制基础','Quiet-STaR','在普通文本每个位置生成解释未来文本的rationale，通过并行采样和训练学习内部思考。','零样本GSM8K 5.9%到10.9%，CommonsenseQA 36.3%到47.2%。','把思考学习从问答专用数据扩展到一般文本的难预测位置。','绝对性能仍有限，训练思考有成本；不是直接证明当代超长数学链质量。','训练数据/潜空间/行为策略')
add('P18','错误机制与诊断','Intrinsic self-correction critique','区分无外部反馈的自我修订与依赖额外反馈的纠错，系统测试前者。','在所测推理设置中常不能提升，部分模型在自纠错后反而下降。','同一个错误信念重复检视不产生独立证据，还可能改坏正确答案。','研究对象是未专门学会有效纠错的模型；不能用标题否定SCoRe等训练后的能力。','纠错恢复/验证反馈/评价设计')
add('P19','错误机制与诊断','Reasoning Models Don’t Always Say…','给正确/错误提示线索，检验模型是否在CoT中承认实际使用线索。','6类提示实验中，使用线索时的显式承认率常低于20%；结果奖励RL也未使忠实度饱和。','文本解释可能遗漏真正驱动答案的信息。','忠实度不是最终答案准确率；任务、模型、提示类型影响显著。','过程诊断/因果干预/评价设计')
add('P20','错误机制与诊断','The Illusion of Thinking','在可控复杂度的规划谜题中比较reasoning与non-reasoning模型及轨迹。','观察到低复杂度非推理模型占优、中等复杂度长推理受益、高复杂度双方失败的分区。','难度改变时，更多生成未必带来有效算法执行，甚至未用满预算就塌缩。','是受控谜题证据，不是证明所有LRM不具推理；输出格式、长度和解法要求是重要边界。','过程诊断/评价设计/能力边界')
add('P21','错误机制与诊断','RLVR vs base capacity','用pass@k、覆盖和似然分析区分采样效率与可解题覆盖。','在所测设置中RLVR提高小k表现，但base在大k时可追上或超过；训练后覆盖可能缩窄。','奖励重分配已有成功路径的概率，不必创造新解题策略。','有限pass@256不是数学上的能力上界；依赖模型、数据、解码和RL配方。','评价设计/训练目标/搜索与分支')
add('P22','错误机制与诊断','RLVR implicitly correct reasoning','研究仅有最终可验证奖励是否也能隐式偏好正确中间推理。','给出理论和实验支持：终局奖励能够对中间推理形成隐式选择；不填单一跨任务提升率。','中间过程与最终成功具有统计关联，终局奖励并非对过程完全无信息。','不等于每步都被正确监督，更不等于已证明超越base所有能力。','训练目标/信用分配/机制理论')
add('P23','机制基础','Expressive Power of CoT','用复杂度理论刻画允许不同数量scratchpad步骤的Transformer表达能力。','在给定模型/精度等假设下，更多CoT步骤扩展可表达计算类；多项式步数对应P类刻画。','额外自回归步骤可以承担真正计算深度。','是表达能力定理，不证明训练能学会这些算法，也没有现实模型准确率数字。','计算深度/机制理论')
add('P24','验证与信用分配','Math-Shepherd','用自动构造的步级监督训练PRM，再做重排和逐步PPO。','Mistral-7B：GSM8K 77.9%到84.1%，再验证达89.1%；MATH 28.6%到33.0%，再验证达43.5%。','用可扩展的自动监督替代大量人工步标签，并把信息用于训练/筛选。','自动标签与当前rollout策略相关，不是无误真理；重排额外采样成本需计入。','验证反馈/训练监督/信用分配')
add('P25','训练与自演化','ReST-MCTS*','由PRM指导树搜索，提取过程价值和成功轨迹，交替自训练策略与价值模型。','Llama3-8B的MATH 20.76→31.42→34.28；但Mistral-MetaMath为29.34→31.06→24.40。','搜索、价值学习和数据再生成构成正反馈，成功率不是唯一训练标签。','非所有骨干/基准单调提升；oracle答案、搜索成本、自动负例标注假设都重要。','搜索与分支/训练数据/信用分配')
add('P26','表示与执行','SpecReason','小模型草拟简单步骤，大模型用单token效用评分接受或重做，并可叠加token级speculation。','作者报告1.4–3.0倍实际推理加速及0.4–9.0%的准确率增益；叠加speculative decoding再减少8.8–58.0%延迟。','只把易步骤交给小模型，验证仅短prefill；不要求思考逐token完全相同。','需要额外小模型和高接受率；原实现同卡轮流执行，并非已做内核并行。','执行系统/验证反馈/模型路由')
add('P27','机制基础','CoT decoding without prompting','从top-k备选token路径中寻找预训练模型已有的推理路径，而非只用贪心。','在多项推理基准中，无CoT示例也能通过解码显露推理能力。','生成分布内可能已有有用路径，触发/选择机制也是瓶颈。','探索替代路径有成本；不是所有长链行为都无需训练即可出现。','解码策略/搜索与分支')
add('P28','机制基础','Graph of Thoughts','把thought组织为任意依赖图，支持合并、提炼和循环反馈。','排序任务相对ToT质量提高62%、成本降低超过31%。','可重用和聚合中间结果，避免把全部问题强制成一条链或互不相交的树。','是特定任务/图操作下的结果；外部thought图不等于模型内部计算图。','过程表征/搜索与分支/状态记忆')
add('P29','错误机制与诊断','TRACE structural analysis','切分最小完整sub-thought、推断话语关系，构造细粒度思维推进图。','简单任务上长思考模型慢5–20倍而无明显准确率收益；识别Explorer与Late Landing两种模式。','冗余来源可区分为过度探索和过度验证，而不只是字数多。','话语标注图仍需独立校验，不能直接当成内部因果依赖。','过程诊断/过程表征')
add('P30','训练与自演化','Behavioral Essence of Distillation','分离事实正确性、题目多样性和推理行为；比较正/负轨迹及已会做的题，并研究损失随复杂度的变化。','错误轨迹/有限题集仍保留多数蒸馏收益；表2的4B训练集诊断NLL正/负为36.4%/34.6%。','重组已有知识的行为模式可能是部分模型的主要瓶颈；复杂长链需保留低概率但关键的学习信号。','表2不是独立测试；不意味着事实不重要。结论限所测1.7B–14B等模型；-p在复杂链上不一定优于CE。','训练数据/训练目标/行为策略')
add('P31','错误机制与诊断','CoT supervision theory','在线性回归梯度下降轨迹模型中，分析有限teacher CoT与测试长程推理稳定性。','刻画相变及误差累积/误差放大：该模型中可分别呈二次、指数MSE增长；更多训练CoT不一定单调更好。','局部近似正确的递推算子可能在长时间反复应用后不稳定。','不能把简化线性模型定理直接当成真实LLM已证实机制。','机制理论/训练监督/长程稳定性')
add('P32','验证与信用分配','DART','动态rollout树发现有收益的工具调用，按父子/全局成功差给子轨迹信用，再做RL。','4B-Thinking上AIME25：DAPO 61.53%、DART 65.56%；但8B上DART 57.64%低于UTIR 61.11%。','奖励真正帮助成功的工具分支，避免只按调用次数奖励造成空调用。','工具多不等于更准；8B部分pass@1未占优，训练2,795难题、16k长度及工具沙箱成本要一起看。','工具交互/搜索与分支/信用分配')
add('P33','验证与信用分配','VCORE','用梯度方向效用推导token Gibbs权重，再用方差控制缩放训练更新。','表1宏平均31.03对SFT 28.97；Qwen3-4B ID/OOD 36.09/32.87。但32B OOD低于DFT。','集中学习有用token，同时避免过尖权重使梯度方差爆炸。','提升不是每个模型/域都成立；额外独立batch和扰动前向有训练成本。已视觉核对表1。','训练监督/训练目标/信用分配')
add('P34','训练与自演化','ThinkLogit','用小reasoning guider与大non-reasoning target的logit算术迁移推理行为；另训练小guider做DPO。','Qwen2.5-32B配1.5B guider，六基准平均相对提升21.5%；DPO版本24.2%。','可能通过解码重分配激活大模型已有能力，避免更新大模型参数。','是相对提升，不是百分点；另一个模型及logit计算并不免费，“可并行低开销”需平台实测。','行为策略/解码策略/模型路由')
add('P35','验证与信用分配','STOP / ECN','student自蒸馏成功轨迹，节点分割/树标注后保留最早正确结论前缀，再LoRA SFT。','表1：Qwen GSM8K 90.1→91.1%、tokens −27.8%；AIME24 36.7→46.7%。Llama GSM8K反而84.0→83.2%。','on-policy内容减少teacher/student分布错位，结构性结论节点比随机截断更完整。','ECN用Gold构造训练目标；不是在线oracle早停。部分正文/表格表述不一致，本报告采用表1并保留风险提示。','训练数据/过程表征/过程压缩')
add('P36','表示与执行','TokenSkip','按语义重要性压缩CoT，混合压缩比例数据SFT，使模型学会跳过低价值词元。','Qwen2.5-14B在GSM8K tokens约313→181，作者概括约40%减少、性能损失<0.4%。','缩短语言实现，训练关键推导之间的连接，而非临时切断推理。','短GSM8K上的效果不能直接外推万token链；与其他论文低数据复现结果不能裸比。','过程压缩/训练数据/训练监督')
add('P37','验证与信用分配','GRP / PASC-GRPO','让模型生成带认知标签的推理图；结构奖励与正确性分层裁剪，防止格式奖励盖过答对。','Qwen3-8B MATH500：Base60.08→GRP-SFT81.60→PASC-GRPO91.20%；AIME24 10→40→46.67%。','图结构使过程可评价，分层约束防止“图很好看但答案错”的奖励投机。','增益包含SFT和RL多阶段，不能全归于图格式；任务验证和图标注仍有成本。','过程表征/训练目标/信用分配')
add('P38','错误机制与诊断','Streaming hallucination','把逐步幻觉判别作为局部观测，维护累计prefix状态而非孤立判断每一步。','作者报告步级和prefix级准确率均超过87%；不同位置的F1/AUC变化明显。','长程错误可传播，局部一句话正确不足以判断整条历史是否可靠。','检测不等于修复；位置和类别不平衡影响准确率解释，状态标注/探针需核对。','过程诊断/状态记忆/验证反馈')
add('P39','错误机制与诊断','Thinking Traps / TAAR','预测错误锁死的起点和逃逸概率，截到陷阱前再以不同强度重启。','DAPO-MATH整理失败子集中89%带陷阱；五个数学/科学基准上匹配预算改善表现。','过早错误承诺会支配后续“反思”，需要改变前缀而非继续附加相似内容。','89%不是全部任务总体比例；依赖诊断策略、截断位置和重启成本。','过程诊断/纠错恢复/状态记忆')
add('P40','训练与自演化','Boundary-aware Curriculum RL','先用pass@k定位base经验边界，对边界附近/之外给teacher指导，再RL巩固。','平均pass@256比base提高9.8个百分点，比vanilla RLVR提高10.3个百分点。','新指导引入原本不易发现的模式，RL再提高这些模式的生成概率。','含外部teacher，不能说纯RL凭空产生所有新能力；pass@256仍是有限采样代理。','训练数据/课程学习/训练目标')
add('P41','错误机制与诊断','Reasoning Theater','比较activation probe、强制提前回答和CoT monitor，分析内部信念与外显文字。','两大模型上probe引导的token减少最高MMLU80%、GPQA30%，准确率相近。','易回忆题可能早已形成答案，难多跳题则仍存在真实信念变化。','可解码不等于答案已正确/计算已完成；探针训练和开放答案迁移是边界。','过程诊断/激活探针/评价设计')
add('P42','终止与风险边界','DEER / PRo','在推理转折点诱导试答并评估置信；PRo聚合多提示置信并惩罚波动。','11个模型、10个基准中，作者报告CoT长度减少19.1–80.1%，准确率增加0.3–5.0%。','在部分状态中，试答置信可暴露足够推理信息；并行/缓存减少检测成本。','范围来自不同设置，不能拼成一个同时最优结果；试答不是免费，也不保证长链未来无修复。','终止控制/验证反馈/执行系统')
add('P43','终止与风险边界','PUMA','先检测推理级语义冗余，再做答案级验证，保留较连贯的推理前缀。','5个LRM/5基准平均token减少26.2%，作者报告保持准确率和保留链质量。','把答案ready与推理converged分开，两个信号互补。','语义相似不是逻辑冗余证明；验证开销和新任务有效性仍需测量。','过程诊断/验证反馈/终止控制')
add('P44','终止与风险边界','Conformal Thinking','设置高/低双阈值，在验证集上以风险控制选择预算与停止策略。','在作者多模型/任务设置达到用户指定风险目标并降低计算；摘要没有可跨设置统一的速度数字。','把经验阈值选择变成统计检验问题。','保证依赖抽样/冻结/损失等假设；不能直接套到任意部署分布，也不是推理能力新来源。','终止控制/统计校准/计算分配')
add('P45','终止与风险边界','Stable Answers, Unfinished Reasoning','预声明3520种self-consensus规则，检查一致、成本和风险能否同时成立。','其固定验收条件下规则均未过三门槛；某省32%token配置约每9次stop有1次提交后续会放弃的答案。','一致反复测的是同一读出过程稳定性，未必测到推理完成。','只否定所测单独一致性信号和规则族，不证明所有主动干预都无效。','过程诊断/终止控制/评价设计')
add('P46','综述入口','Long-CoT survey','区分Short/Long CoT，按深推导、广探索、可行反思等特点组织研究。','提供谱系与研究问题分类，不是一个需要对比准确率的新算法。','避免把长链只理解为增加字数。','综述的空白判断需要用2026新论文更新，不能代替原文核对。','文献索引/过程表征')
add('P47','综述入口','Reasoning SFT survey 2026','从数据、算法、优化动力学、机制解释整理reasoning SFT。','覆盖近期SFT研究与瓶颈，不提供统一算法性能值。','SFT效果受数据特征、训练目标和模型底座共同影响。','2026年10月预印本，是选题入口而非具体创新或定论。','文献索引/训练监督')
add('P48','验证与信用分配','Echo Trap / TRAE','用tree-structured rollouts估计每轮反思的advantage，抑制复制反思和探索塌缩。','Qwen3-8B-Base六数学基准平均36.1→56.2%；多轮反思进一步改善。','整轨迹同奖无法区分有用修订与重复，分轮信用让学习信号更精确。','训练树和轮级reward需要成本；反思轮数/采样预算要与基线匹配。','信用分配/行为策略/纠错恢复')
add('P49','相邻长程恢复','DeepRewind','用二元提交控制、typed研究状态图和依赖回退修复过早承诺。','DRBench/LiveDRBench上insight recall +3.6个百分点，过早承诺相对减少59.1%。','撤回受影响子图，同时保留独立证据，避免错误解释自我强化。','REALM2026 workshop，不是ACL主会；Deep Research agent不同于单模型内部CoT。','状态记忆/纠错恢复/验证反馈')
add('P50','验证与信用分配','SPAE','训练时诱导短试答，结合熵置信和Gold token似然构造Step Potential，塑形逐步advantage。','Qwen7B平均准确率61.10→63.86%，tokens9023→6825；Qwen3-4B 70.32→70.77%，tokens10903→7250。','区分有进展的解题、无效检查和自信错误，对潜势变化分配信用。','training-free的是探针不新增参数，不是整个方法无需训练；Gold似然不能直接用于在线决策。','信用分配/训练目标/过程诊断')
add('P51','训练与自演化','DeepSeek-R1','可验证终局奖励驱动RL，辅以冷启动、拒绝采样SFT和多域对齐；再蒸馏小模型。','R1报告AIME2024 pass@1 79.8%、MATH50097.3%；R1-Zero观察到反思和自验证行为发展。','可靠结果反馈与大规模探索可选择长程解题行为；冷启动改善可读性及训练起点。','奖励仍依赖Gold/测试；作者也报告PRM/MCTS大规模训练成本和reward hacking局限，不能照搬所有模块。','训练目标/训练数据/行为策略')
add('P52','相邻长程恢复','Dependency-guided rollback repair','在memory→action依赖图上撤回错误后果，保留独立支持，选择性重放相关计算。','150例控制基准恢复85.3%对77.3%，调用减41.8%；但复发26.6%高于LLM-judge12.1%。','删错源不等于清除已传播后果；选择性恢复降低重算成本。','已给定故障执行与诊断错记忆；持久memory agent不等于KV/单链，局部成功可能增加后续复发。','状态记忆/纠错恢复/依赖追踪')
add('P53','相邻长程恢复','CriticSearch','冻结critic在训练时用整段轨迹和Gold回看每一轮，提供非对称密集反馈。','多跳搜索问答中收敛更快、训练更稳、表现更好；本轮不填未核对统一百分比。','训练时允许额外信息改善信用估计，推理时不必获得同样oracle。','critic错误和训练成本需计入；不能把训练privileged信息泄露到在线控制。','工具交互/信用分配/验证反馈')
add('P54','相邻长程恢复','Logic Tree','把DeepResearch任务组织为可恢复DAG，局部回退、全局重规划并清理知识状态。','BrowseComp/GAIA/XBench上优于顺序与plan-and-execute基线；有拓扑/恢复消融。','并行处理独立子问题，错误出现时保留已验证结果再重规划。','不同于单链token推理；图维护和调度成本、来源可靠性都是前提。','过程表征/状态记忆/纠错恢复/执行系统')
add('P55','错误机制与诊断','Measuring CoT Faithfulness','通过改错、改写等干预检验答案是否因果依赖其文字推导。','模型/任务间差异大，部分答案忽略CoT；大模型在多数所测任务中更不忠实。','性能提升、外显说明和内部因果作用需要分开测量。','具体干预可能未击中关键位置；不能从一类扰动无效推出所有CoT均无因果作用。','过程诊断/因果干预/评价设计')
add('P56','表示与执行','LaTER','连续latent先探索，保留KV后切回显式CoT验证；可训练latent rollout/切换行为。','Qwen3-14B训练外版本AIME25 70.0→73.3%，tokens15730→10661；训练版本80.0%，较CoT少33%token。','把潜式探索和需要精确符号处理的显式阶段分工，切换接口避免从头重算。','通用“潜式+显式验证”已有此工作；latent步数/KV缓存和训练数据69k仍有成本。','潜空间/验证反馈/阶段路由')
add('P57','表示与执行','HRPO','可学习门控混合token embedding与前一hidden，逐步增加latent比重并RL。','知识/推理基准优于若干显式与latent基线，输出趋短；摘要无统一提升值。','保留token采样随机性，使连续表示路线还能进行policy optimization。','门控学习不是免费推理；不需要CoT轨迹不等于不需要奖励和训练资源。','潜空间/训练目标/行为策略')
add('P58','错误机制与诊断','CRV','训练transcoder替换MLP，构造attribution graph，再从结构特征检测并干预错误。','计算图结构可预测推理错误；targeted transcoder feature干预能修正部分错误；特征跨域迁移有限。','把“哪里像错”推进到计算过程的结构签名，并检验部分因果作用。','研究对象是可解释replacement model；重建误差、white-box成本和域特异性重要。','过程诊断/因果干预/计算图')
add('P59','错误机制与诊断','RELIEF','用logit探针读自我推理信念，再以合成自反QA微调目标行为。','Qwen3-8B四基准平均84.7→86.1%、token比例71.3%；学生训练约0.4M token。','用行为先验重塑已有能力的调用，不靠完整正确推理轨迹监督。','不是生成新的知识或技能；信念话语不自动等于实际能力，合成数据成本也需计入。','行为策略/训练数据/过程诊断')
add('P60','表示与执行','Pre2 guided latent modeling','区分thinking/answering阶段，分别预测latent引导状态，与显式token联合解码。','一项域内训练、六项OOD直接评估，作者报告一致提升；摘要无统一百分比。','保留显式监督，同时让两种角色的latent状态避免同一next-token目标冲突。','通用“混合显隐推理”已存在；新增latent预测和参数开销需实测。','潜空间/阶段路由/训练监督')
add('P61','多模态扩展','HyLaR / DePO','交替文本与连续视觉latent，分开约束两类动作的policy update。','在细粒度感知及一般多模态基准优于所测标准/latent基线；作者注明ECCV2026。','避免将视觉状态过早语言化，同时处理离散/连续策略优化不兼容。','感知任务改善不能直接当文本数学长链提升；两种行动分布的优化条件不同。','潜空间/感知对齐/训练目标')
add('P62','多模态扩展','HyPeR','以PAQA做感知冷启动，再GRPO；加入pause计算和感知一致性奖励。','作者报告MMAU-mini +13.1%、MMAR +25.5%、PAQA +28.2%的准确率增益。','错误可能先来自听错/分离失败，必须先把证据感知对齐再长推理。','论文百分比口径需读表确认；不是所有推理失败都能靠语言反思解决。','感知对齐/潜空间/训练目标/验证反馈')

A={'P04','P05','P07','P08','P10','P14','P15','P21','P25','P26','P30','P31','P32','P33','P35','P37','P38','P39','P48','P49','P50','P51','P52','P54','P56','P57','P58','P59','P60'}
rows=json.loads((ROOT/'references.json').read_text(encoding='utf-8'))
assert len(data)==len(rows)==62
for row in rows:
    row.update(data[row['id']]);row['reading_depth']='A: selective methods/results/ablation reading' if row['id'] in A else 'B: primary metadata/abstract scope verified'
    row['effect_attribution']='Authors reported; not independently reproduced in this survey'
    row['mechanism_evidence_scope']='Selected original methods/results or component controls inspected; not a universal causal proof' if row['id'] in A else 'Authors rationale and survey interpretation; full mechanism not independently checked'
(ROOT/'survey_records.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
groups=list(dict.fromkeys(r['group'] for r in rows))
lines=['# 长思维链研究文献矩阵：62项','',
       '检索截至2026-11-05。A为重点阅读了方法/实验或关键消融，B为原始元数据/摘要级核查；不宣称62篇都全文精读。全部效果为作者报告，不是本项目复现。',
       '', '“为什么可能有效”包括作者解释与调研推断；除具体消融/干预支持的局部结论外，不当作普遍因果定论。',
       '', '基础CoT论文用于机制谱系，不能与现代万token长链直接等同。百分比、百分点、pass@k、平均多次采样准确率、token数和墙钟均按论文语境解释。', '']
for group in groups:
    lines+=['## '+group,'','| 编号/论文 | 思想与做法 | 作者报告的效果/条件 | 为什么可能有效与局限 |','|---|---|---|---|']
    for r in rows:
        if r['group']!=group:continue
        depth='A' if r['id'] in A else 'B'
        venue=r['venue']
        if r['publication_status'].startswith('arxiv'):
            venue='arXiv '+r['year']+'；'+venue if venue!='arXiv preprint' else 'arXiv '+r['year']
        def esc(s):return s.replace('|',r'\|').replace('\n',' ')
        lines.append('| '+r['id']+' ['+esc(r['alias'])+']('+r['source_url']+')<br>'+esc(venue)+'；'+depth+' | '+esc(r['method'])+' | '+esc(r['reported_effect'])+' | '+esc(r['mechanism_interpretation'])+'<br>边界：'+esc(r['conditions_and_limits'])+' |')
    lines+=['']
lines+=['## 引文与状态说明','',
    '出版方/DOI记录直接核验23项；其余39项以arXiv记录为引用，其中若干作者注明被ICLR、NeurIPS、COLM、ECCV等会议接收。作者备注与已核对正式卷页分开，不把under review记成录用。',
    '', '导入文献管理器可用 [BibTeX](references.bib) 或 [RIS](references.ris)。可追踪字段及来源见 [结构化文献与分析](survey_records.json)。']
(ROOT/'文献矩阵_62项.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps({'annotated':len(rows),'deep_selected':len(A),'metadata_abstract':len(rows)-len(A),'groups':len(groups)}))
